import type {
  CloseProps,
  ContentProps,
  DescriptionProps,
  DynamicProps,
  LabelProps,
  OverlayProps,
  TriggerProps,
} from "@corvu/drawer";
import DrawerPrimitive from "@corvu/drawer";

import { cn } from "~/lib/utils.ts";
import type { Component, ComponentProps, JSX, ValidComponent } from "solid-js";

import { splitProps } from "solid-js";

const Drawer = DrawerPrimitive;

const DrawerPortal = DrawerPrimitive.Portal;

const DrawerTrigger = <T extends ValidComponent = "button">(
  props: DynamicProps<T, TriggerProps<T>>,
) => {
  return (
    <DrawerPrimitive.Trigger
      data-slot="drawer-trigger"
      {...(props as TriggerProps)}
    />
  );
};

const DrawerClose = <T extends ValidComponent = "button">(
  props: DynamicProps<T, CloseProps<T>>,
) => {
  return (
    <DrawerPrimitive.Close
      data-slot="drawer-close"
      {...(props as CloseProps)}
    />
  );
};

type DrawerOverlayProps<T extends ValidComponent = "div"> = OverlayProps<T> & {
  class?: string;
};

const DrawerOverlay = <T extends ValidComponent = "div">(
  props: DynamicProps<T, DrawerOverlayProps<T>>,
) => {
  const [local, rest] = splitProps(props as DrawerOverlayProps, [
    "class",
    "style",
  ]);
  const drawerContext = DrawerPrimitive.useContext();
  return (
    <DrawerPrimitive.Overlay
      data-slot="drawer-overlay"
      class={cn(
        "bg-black/10 supports-backdrop-filter:backdrop-blur-xs fixed inset-0 z-50 data-transitioning:transition-opacity data-transitioning:duration-300",
        props.class,
      )}
      // the drag/close fade rides on opacity, so a consumer style has to merge
      // with it rather than replace it
      style={typeof local.style === "string"
        ? `opacity:${drawerContext.openPercentage()};${local.style}`
        : { opacity: drawerContext.openPercentage(), ...local.style }}
      {...rest}
    />
  );
};

type DrawerContentProps<T extends ValidComponent = "div"> = ContentProps<T> & {
  class?: string;
  children?: JSX.Element;
};

const DrawerContent = <T extends ValidComponent = "div">(
  props: DynamicProps<T, DrawerContentProps<T>>,
) => {
  const [, rest] = splitProps(props as DrawerContentProps, [
    "class",
    "children",
  ]);
  return (
    <DrawerPortal>
      <DrawerOverlay />
      <DrawerPrimitive.Content
        data-slot="drawer-content"
        class={cn(
          "bg-popover text-popover-foreground flex h-auto flex-col text-xs/relaxed data-[side=bottom]:rounded-none data-[side=bottom]:border-t data-[side=left]:rounded-none data-[side=left]:border-r data-[side=right]:rounded-none data-[side=right]:border-l data-[side=top]:rounded-none data-[side=top]:border-b group/drawer-content fixed z-50 data-[side=bottom]:inset-x-0 data-[side=bottom]:bottom-0 data-[side=bottom]:mt-24 data-[side=bottom]:max-h-[80vh] data-[side=left]:inset-y-0 data-[side=left]:left-0 data-[side=left]:w-3/4 data-[side=right]:inset-y-0 data-[side=right]:right-0 data-[side=right]:w-3/4 data-[side=top]:inset-x-0 data-[side=top]:top-0 data-[side=top]:mb-24 data-[side=top]:max-h-[80vh] data-[side=left]:sm:max-w-sm data-[side=right]:sm:max-w-sm data-transitioning:transition-transform data-transitioning:duration-300",
          props.class,
        )}
        {...rest}
      >
        <div class="bg-muted mt-4 h-1 w-[100px] rounded-none mx-auto hidden shrink-0 group-data-[side=bottom]/drawer-content:block" />
        {props.children}
      </DrawerPrimitive.Content>
    </DrawerPortal>
  );
};

const DrawerHeader: Component<ComponentProps<"div">> = (props) => {
  const [, rest] = splitProps(props, ["class"]);
  return (
    <div
      data-slot="drawer-header"
      class={cn(
        "gap-0.5 p-4 md:gap-0.5 md:text-left flex flex-col group-data-[side=bottom]/drawer-content:text-center group-data-[side=top]/drawer-content:text-center",
        props.class,
      )}
      {...rest}
    />
  );
};

const DrawerFooter: Component<ComponentProps<"div">> = (props) => {
  const [, rest] = splitProps(props, ["class"]);
  return (
    <div
      data-slot="drawer-footer"
      class={cn("gap-2 p-4 mt-auto flex flex-col", props.class)}
      {...rest}
    />
  );
};

type DrawerTitleProps<T extends ValidComponent = "div"> = LabelProps<T> & {
  class?: string;
};

const DrawerTitle = <T extends ValidComponent = "div">(
  props: DynamicProps<T, DrawerTitleProps<T>>,
) => {
  const [, rest] = splitProps(props as DrawerTitleProps, ["class"]);
  return (
    <DrawerPrimitive.Label
      data-slot="drawer-title"
      class={cn(
        "text-foreground text-sm font-medium font-heading",
        props.class,
      )}
      {...rest}
    />
  );
};

type DrawerDescriptionProps<T extends ValidComponent = "div"> =
  & DescriptionProps<T>
  & {
    class?: string;
  };

const DrawerDescription = <T extends ValidComponent = "div">(
  props: DynamicProps<T, DrawerDescriptionProps<T>>,
) => {
  const [, rest] = splitProps(props as DrawerDescriptionProps, ["class"]);
  return (
    <DrawerPrimitive.Description
      data-slot="drawer-description"
      class={cn("text-muted-foreground text-xs/relaxed", props.class)}
      {...rest}
    />
  );
};

export {
  Drawer,
  DrawerClose,
  DrawerContent,
  DrawerDescription,
  DrawerFooter,
  DrawerHeader,
  DrawerOverlay,
  DrawerPortal,
  DrawerTitle,
  DrawerTrigger,
};
